package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.StringUtils;
import org.apache.commons.lang.Validate;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_prepend_TriageGen2Test {

    @Test
    public void testPrepend_ValidHtml_AddsToFront() {
        Element parent = new Element("div", "");
        parent.append("<span>Existing</span>");

        String newHtml = "<p>New</p><i>Also New</i>";
        parent.prepend(newHtml);

        // The logic iterates backwards through nodes and calls prependChild.
        // Fragment nodes: <p>, <i>. 
        // Iteration 1 (i=1): node = <i>. parentNode set to null. prependChild(<i>). Parent: [<i>, <span>]
        // Iteration 2 (i=0): node = <p>. parentNode set to null. prependChild(<p>). Parent: [<p>, <i>, <span>]

        String expectedHtml = "<p>New</p><i>Also New</i><span>Existing</span>";
        Assert.assertEquals(expectedHtml, parent.html());
    }

    @Test
    public void testPrepend_TextContent() {
        Element parent = new Element("div", "");
        parent.append("<span>Content</span>");

        parent.prepend("Just Text");

        // Text nodes are treated as nodes in the fragment.
        // Fragment nodes: TextNode("Just Text")
        // Expected: Just Text<span>Content</span>
        Assert.assertEquals("Just Text<span>Content</span>", parent.html());
    }

    @Test
    public void testPrepend_EmptyHtml() {
        Element parent = new Element("div", "");
        parent.append("<span>Content</span>");

        parent.prepend("");

        // Parser.parseBodyFragment("") results in an empty body.
        // nodes.size() will be 0. No changes.
        Assert.assertEquals("<span>Content</span>", parent.html());
    }

    @Test(expected = NullPointerException.class)
    public void testPrepend_NullHtml_ThrowsException() {
        Element parent = new Element("div", "");
        // Validate.notNull(html) should throw NullPointerException
        parent.prepend(null);
    }

    @Test
    public void testPrepend_ReturnsSelf() {
        Element parent = new Element("div", "");
        Element result = parent.prepend("<span>test</span>");

        Assert.assertSame(parent, result);
    }

    @Test
    public void testPrepend_ComplexStructure() {
        Element parent = new Element("ul", "");
        parent.append("<li>Item 1</li>");

        String newHtml = "<li>Item 0</li><div class='wrapper'><span>Nested</span></div>";
        parent.prepend(newHtml);

        // Expected order: <li>Item 0</li>, <div class='wrapper'><span>Nested</span></div>, <li>Item 1</li>
        String expected = "<li>Item 0</li><div class=\"wrapper\"><span>Nested</span></div><li>Item 1</li>";
        Assert.assertEquals(expected, parent.html());
    }
}
